import{_ as t,o,c as a,a3 as i}from"./chunks/framework.EDt1A0Ag.js";const c=JSON.parse('{"title":"关于我们 | 全球机场 (AirportMatrix) 评测实验室","description":"AirportMatrix 实验室简介、团队专业背景、独立编辑准则与网络工程测试使命。","frontmatter":{"title":"关于我们 | 全球机场 (AirportMatrix) 评测实验室","description":"AirportMatrix 实验室简介、团队专业背景、独立编辑准则与网络工程测试使命。"},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1792908240000}'),e={name:"about.md"};function l(n,r,s,d,h,g){return o(),a("div",null,[...r[0]||(r[0]=[i('<h1 id="🌿-关于-airportmatrix-评测实验室" tabindex="-1">🌿 关于 AirportMatrix 评测实验室 <a class="header-anchor" href="#🌿-关于-airportmatrix-评测实验室" aria-label="Permalink to &quot;🌿 关于 AirportMatrix 评测实验室&quot;">​</a></h1><p>欢迎访问 <strong>全球机场 · 森林知识屋 (AirportMatrix)</strong>。我们是一个由网络工程师、分布式系统开发者与海外学术研究者自发组建的独立网络连通性评测与协议研究实验室。</p><hr><h2 id="🎯-我们的使命与初衷" tabindex="-1">🎯 我们的使命与初衷 <a class="header-anchor" href="#🎯-我们的使命与初衷" aria-label="Permalink to &quot;🎯 我们的使命与初衷&quot;">​</a></h2><p>在跨境网络访问与学术科研领域，用户长期面临信息不对称与虚假宣传的困扰：</p><ul><li><strong>劣质中继充当内网专线</strong>：大量服务商以廉价公网中转冒充高成本 IPLC/IEPL 专线，在晚高峰骨干网拥塞时丢包率骤增至 30% 以上。</li><li><strong>流媒体与 AI 解锁虚标</strong>：声称原生住宅双 ISP IP，实际为高风险数据中心机房 IP，导致 ChatGPT 频繁遭遇 <code>Access Denied</code> 或风控降智。</li><li><strong>商业水军与无底线吹捧</strong>：评测内容高度同质化，掩盖晚高峰限速、月付跑路、退款无门等关键风险。</li></ul><p><strong>AirportMatrix 实验室的创立目标</strong>：构建一套透明、量化、基于真实全天候多运营商实测的评测标准，以网络工程视角拆解底层链路技术，帮助科研人员、出海工程师、跨境电商从业者与海外留学生挑选安全、稳定、高性价比的网络工具。</p><hr><h2 id="🔬-评测团队与技术架构分工" tabindex="-1">🔬 评测团队与技术架构分工 <a class="header-anchor" href="#🔬-评测团队与技术架构分工" aria-label="Permalink to &quot;🔬 评测团队与技术架构分工&quot;">​</a></h2><p>我们的编辑与技术研究协作围绕三大实证方向展开：</p><ul><li><strong>网络拓扑与路由研究组</strong>：专注于 BGP 选路分析、晚高峰抖动评估及 IPLC/IEPL 物理内网专线时延特征研究。</li><li><strong>协议指纹与风控检测组</strong>：专注于 TLS 1.3 指纹、VLESS/SS2022/Hysteria2 传输特征及海外应用（ChatGPT/Claude/Netflix）IP 纯净度验证。</li><li><strong>数据采集与归档规范组</strong>：结合主流开源/社区测速探针工具（如 <code>MAI-TEST-BOT</code>、<code>MiaoKo</code>、<code>MiaoSu</code> 等带时间戳与节点批次信息的实测快照）及定期复核机制，建立可追溯的公开对比档案。</li></ul><hr><h2 id="🛡️-编辑独立性与透明分级准则" tabindex="-1">🛡️ 编辑独立性与透明分级准则 <a class="header-anchor" href="#🛡️-编辑独立性与透明分级准则" aria-label="Permalink to &quot;🛡️ 编辑独立性与透明分级准则&quot;">​</a></h2><p>为避免“用未核实资料充当实测结果”，本站严格执行以下四条公开规范：</p><ol><li><strong>四级数据来源显式隔离</strong>：本站将收录的 42 家服务商明确区分为「有实测/解锁原图（含时间戳与工具版本）」「厂商参考参数与非晚高峰测速」「品牌公开资料」及「历史归档/待核实」，绝不将未经测速确认的条目伪装为实测数据。</li><li><strong>拒绝付费篡改评测结论</strong>：我们不接受任何厂商通过付费、充值或赞助要求修改评测局限说明或虚构实测快照成绩的行为。</li><li><strong>数据优先与原始参数留存</strong>：每份带有测速截图的评测页面均保留原始测试时间、测试工具版本、电信/联通/移动后端标注及局限提示，方便读者自行核对。</li><li><strong>定期复测与降级机制</strong>：网络服务质量具有时效性。对于缺少近期连续实测数据、优惠码状态存疑或官网入口变更的服务商，本站将其自动标为「待核实」并移入后排档案区。</li></ol><hr><h2 id="🏗️-评测基础设施" tabindex="-1">🏗️ 评测基础设施 <a class="header-anchor" href="#🏗️-评测基础设施" aria-label="Permalink to &quot;🏗️ 评测基础设施&quot;">​</a></h2><p>为了杜绝单点测试的片面性，我们在中国大陆主要骨干网络枢纽节点部署了自建测试探针：</p><ul><li><strong>电信骨干节点</strong>：上海电信 CN2/163 出口、广州电信骨干出口；</li><li><strong>联通骨干节点</strong>：北京联通、山东联通 AS4837/AS9929 出口；</li><li><strong>移动骨干节点</strong>：广东移动、江苏移动 CMI 出口；</li><li><strong>测试时间窗口</strong>：覆盖平日低峰期（10:00 - 16:00）、晚高峰拥塞期（20:00 - 23:30）以及节假日负载波动期。</li></ul><p>详细测试方法与量化指标请查阅 <a href="/methodology">评测方法论与质检标准</a>。</p><hr><h2 id="📬-联系方式与勘误反馈" tabindex="-1">📬 联系方式与勘误反馈 <a class="header-anchor" href="#📬-联系方式与勘误反馈" aria-label="Permalink to &quot;📬 联系方式与勘误反馈&quot;">​</a></h2><p>我们鼓励读者、同行专家与技术社区监督我们的评测报告。若您在阅读过程中发现任何数据偏差、品牌配置变更或链接失效，欢迎通过以下渠道与实验室联系：</p><ul><li><strong>官方邮箱</strong>：<code>admin@airportmatrix.homes</code></li><li><strong>站内故障与勘误自检</strong>：<a href="/faq/timeout-troubleshoot">30 秒故障诊断与规则核对中心</a> · <a href="/methodology">评测方法论与数据口径</a></li><li><strong>勘误承诺</strong>：在收到有效技术证据（如带时间戳的测速截图、套餐后台截图或路由追踪 MTR 日志）后，我们将在 48 小时内核实并修订对应品牌档案。</li></ul>',24)])])}const u=t(e,[["render",l]]);export{c as __pageData,u as default};
